  nhVt3: string;
  nhVt4: string;
  nhVt5: string;
  dienGiai: string;
  tien1: string;
  tien2: string;
  strField: string;
  strValue: string;
  locNsd: boolean;
  maVv: string;
  maHd: string;
  maPhi: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
