const emptySearch = (): SearchState => ({
  ngayCt1: '',
  ngayCt2: '',
  maPost: '',
  maGd: '',
  maQuyen: '',
  soCt1: '',
  soCt2: '',
  tkNo: '',
  tkCo: '',
  maKh: '',
  maKho: '',
  maKhoN: '',
  maVt: '',
  nhVt1: '',
  nhVt2: '',
  nhVt3: '',
  nhVt4: '',
  nhVt5: '',
  dienGiai: '',
  tien1: '',
  tien2: '',
  strField: '',
  strValue: '',
  locNsd: false,
  maVv: '',
  maHd: '',
  maPhi: '',
  maSp: '',
  maKu: '',
  maTtln: '',
  maTtcp: '',
  maBp: '',
  maHs: '',
  maCd: '',
  maTd1: '',
  maTd2: '',
  maTd3: '',
  maTd4: '',
  maTd5: '',
});

function showMoney(value: number | null | undefined): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value ?? 0);
}

function formatDate(value: string | null | undefined): string {
  if (!value) return '';
  try {
    const parsed = parseISO(value);
    if (Number.isNaN(parsed.getTime())) return value;
    return format(parsed, 'dd/MM/yyyy');
  } catch {
    return value;
  }
}

function amountQuery(raw: string): number | undefined {
  const text = raw.trim();
  if (!text) return undefined;
  const value = Number(text.replace(',', '.'));
  if (!Number.isFinite(value) || value === 0) return undefined;
  return value;
}

function buildSearchQuery(search: SearchState): Record<string, string | number | boolean> {
  const query: Record<string, string | number | boolean> = {};
  const textKeys: Array<keyof SearchState> = [
    'ngayCt1', 'ngayCt2', 'maQuyen', 'soCt1', 'soCt2', 'tkNo', 'tkCo', 'maKh', 'maKho', 'maKhoN', 'maVt',
    'nhVt1', 'nhVt2', 'nhVt3', 'nhVt4', 'nhVt5', 'dienGiai', 'maVv', 'maHd', 'maPhi', 'maSp',
    'maKu', 'maTtln', 'maTtcp', 'maBp', 'maHs', 'maCd', 'maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5',
  ];
  textKeys.forEach(key => {
    const value = String(search[key]).trim();
    if (value) query[key] = value;
  });
  if (search.maPost === '3' || search.maPost === '9') query.maPost = search.maPost;
  if (search.maGd === '4' || search.maGd === '9') query.maGd = search.maGd;
  const tien1 = amountQuery(search.tien1);
  const tien2 = amountQuery(search.tien2);
  if (tien1 !== undefined) query.tien1 = tien1;
  if (tien2 !== undefined) query.tien2 = tien2;
  if (search.strField && search.strValue.trim()) {
    query.strField = search.strField;
    query.strValue = search.strValue.trim();
  }
  if (search.locNsd) query.locNsd = true;
  return query;
}

function Field(props: {
  label: string;
  testId: string;
  value: string;
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
  maxLength?: number;
  inputMode?: 'decimal' | 'text';
  type?: string;
  span?: boolean;
}) {
  return (
    <div className={props.span ? df.spanCol2 : undefined}>
      <label className={df.label}>{props.label}</label>
      <Input
        type={props.type}
        inputMode={props.inputMode}
        maxLength={props.maxLength}
        data-testid={props.testId}
        value={props.value}
        onChange={props.onChange}
      />
    </div>
  );
}

const PxeListPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const [search, setSearch] = useState<SearchState>(emptySearch);
  const [applied, setApplied] = useState<SearchState>(emptySearch);
  const [filtering, setFiltering] = useState(false);
  const [items, setItems] = useState<PxeIssueListItem[]>([]);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const keepSelection = (rows: PxeIssueListItem[], current: string) => {
    if (rows.some(row => row.sttRec === current)) return current;
    return '';
  };

  const loadOpen = useCallback(async (locNsd: boolean, current: string) => {
    setLoading(true);
    setError('');
    try {
      const query: Record<string, string | number | boolean> = { loadTop: 5 };
      if (locNsd) query.locNsd = true;
      const rows = await listPxeIssues(query);
      setItems(rows);
      setSelectedSttRec(keepSelection(rows, current));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(getApiErrorMessage(err, 'Không tải được danh sách phiếu xuất điều chuyển kho'));
    } finally {
      setLoading(false);
    }
  }, []);

  const loadSearch = useCallback(async (currentSearch: SearchState, current: string) => {
    setLoading(true);
    setError('');
    try {
      const rows = await listPxeIssues(buildSearchQuery(currentSearch));
      setItems(rows);
      setSelectedSttRec(keepSelection(rows, current));
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(getApiErrorMessage(err, 'Không tải được danh sách phiếu xuất điều chuyển kho'));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadOpen(false, '');
  }, [loadOpen]);

  const setText = (key: keyof SearchState) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearch(prev => ({ ...prev, [key]: event.target.value }));
  };

  const onSearch = () => {
    setFiltering(true);
    setApplied(search);
    void loadSearch(search, selectedSttRec);
  };

  const onRefresh = () => {
    if (filtering) void loadSearch(applied, selectedSttRec);
    else void loadOpen(search.locNsd, selectedSttRec);
  };

  const onEnter = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter' && (event.target instanceof HTMLInputElement || event.target instanceof HTMLSelectElement)) {
      event.preventDefault();
      onSearch();
    }
  };

  const noSelection = !selectedSttRec;

  return (
    <div className={df.page} data-testid="ct-pxe-list">
      <h1 data-testid="ct-pxe-title">Phiếu xuất điều chuyển kho</h1>
      <div className={df.headerActions}>
        <Button variant="secondary" data-testid="ct-pxe-toolbar-refresh-btn" onClick={onRefresh}>Làm mới</Button>
        <Button variant="primary" data-testid="ct-pxe-search-btn" onClick={onSearch}>Tìm</Button>
        <Button variant="primary" data-testid="ct-pxe-toolbar-add-btn" onClick={() => navigate('/kt/pxe/them')}>Thêm</Button>
        <Button variant="secondary" data-testid="ct-pxe-toolbar-edit-btn" disabled={noSelection} onClick={() => navigate(`/kt/pxe/${selectedSttRec}`)}>Sửa</Button>
        <Button variant="secondary" data-testid="ct-pxe-toolbar-view-btn" disabled={noSelection} onClick={() => navigate(`/kt/pxe/${selectedSttRec}?mode=view`)}>Xem</Button>
        <Button variant="secondary" data-testid="ct-pxe-toolbar-copy-btn" disabled={noSelection} onClick={() => navigate(`/kt/pxe/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}>Sao chép</Button>
      </div>

      <section className={df.section} data-testid="ct-pxe-search">
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4} onKeyDown={onEnter}>
          <Field label="Ngày C.từ từ" testId="ct-pxe-search-ngayCt1" type="date" value={search.ngayCt1} onChange={setText('ngayCt1')} />
          <Field label="Ngày C.từ đến" testId="ct-pxe-search-ngayCt2" type="date" value={search.ngayCt2} onChange={setText('ngayCt2')} />
          <Select label="Trạng thái" data-testid="ct-pxe-search-maPost" value={search.maPost} options={[{ value: '', label: 'Tất cả' }, { value: '3', label: 'Lập chứng từ' }, { value: '9', label: 'Hạch toán sổ cái' }]} onChange={event => setSearch(prev => ({ ...prev, maPost: event.target.value }))} />
          <Select label="Loại giao dịch" data-testid="ct-pxe-search-maGd" value={search.maGd} options={[{ value: '', label: 'Tất cả' }, { value: '4', label: 'Xuất điều chuyển kho' }, { value: '9', label: 'Xuất hàng gửi bán' }]} onChange={event => setSearch(prev => ({ ...prev, maGd: event.target.value }))} />
          <Field label="Quyền số" testId="ct-pxe-search-maQuyen" maxLength={30} value={search.maQuyen} onChange={setText('maQuyen')} />
          <Field label="Số C.từ từ" testId="ct-pxe-search-soCt1" maxLength={30} value={search.soCt1} onChange={setText('soCt1')} />
          <Field label="Số C.từ đến" testId="ct-pxe-search-soCt2" maxLength={30} value={search.soCt2} onChange={setText('soCt2')} />
          <Field label="TK nợ" testId="ct-pxe-search-tkNo" maxLength={30} value={search.tkNo} onChange={setText('tkNo')} />
          <Field label="TK có" testId="ct-pxe-search-tkCo" maxLength={30} value={search.tkCo} onChange={setText('tkCo')} />
          <Field label="Đối tượng" testId="ct-pxe-search-maKh" maxLength={30} value={search.maKh} onChange={setText('maKh')} />
          <Field label="Kho xuất" testId="ct-pxe-search-maKho" maxLength={30} value={search.maKho} onChange={setText('maKho')} />
          <Field label="Kho nhập" testId="ct-pxe-search-maKhoN" maxLength={30} value={search.maKhoN} onChange={setText('maKhoN')} />
          <Field label="Hàng hoá" testId="ct-pxe-search-maVt" maxLength={30} value={search.maVt} onChange={setText('maVt')} />
          <Field label="Nhóm hàng 1" testId="ct-pxe-search-nhVt1" maxLength={30} value={search.nhVt1} onChange={setText('nhVt1')} />
          <Field label="Nhóm hàng 2" testId="ct-pxe-search-nhVt2" maxLength={30} value={search.nhVt2} onChange={setText('nhVt2')} />
          <Field label="Nhóm hàng 3" testId="ct-pxe-search-nhVt3" maxLength={30} value={search.nhVt3} onChange={setText('nhVt3')} />
          <Field label="Nhóm hàng 4" testId="ct-pxe-search-nhVt4" maxLength={30} value={search.nhVt4} onChange={setText('nhVt4')} />
          <Field label="Nhóm hàng 5" testId="ct-pxe-search-nhVt5" maxLength={30} value={search.nhVt5} onChange={setText('nhVt5')} />
          <Field label="Diễn giải" testId="ct-pxe-search-dienGiai" maxLength={200} span value={search.dienGiai} onChange={setText('dienGiai')} />
          <Field label="Tiền từ" testId="ct-pxe-search-tien1" inputMode="decimal" value={search.tien1} onChange={setText('tien1')} />
          <Field label="Tiền đến" testId="ct-pxe-search-tien2" inputMode="decimal" value={search.tien2} onChange={setText('tien2')} />
          <Select label="Trường" data-testid="ct-pxe-search-strField" value={search.strField} options={[{ value: '', label: 'Tất cả' }, { value: 'SO_CT', label: 'Số C.từ' }, { value: 'NGAY_CT', label: 'Ngày C.từ' }, { value: 'MA_KH', label: 'Đối tượng' }, { value: 'TEN_KH', label: 'Tên đối tượng' }, { value: 'T_TIEN', label: 'Tổng Phát sinh' }, { value: 'T_TIEN_NT', label: 'Tổng Ps NT' }, { value: 'MA_NT', label: 'Ngoại tệ' }, { value: 'MA_KHO', label: 'Mã kho' }, { value: 'MA_KHON', label: 'Kho nhập' }]} onChange={event => setSearch(prev => ({ ...prev, strField: event.target.value }))} />
          <Field label="Giá trị" testId="ct-pxe-search-strValue" value={search.strValue} onChange={setText('strValue')} />
          <div>
            <Checkbox label="Chỉ chứng từ của tôi" data-testid="ct-pxe-search-locNsd" checked={search.locNsd} onChange={event => setSearch(prev => ({ ...prev, locNsd: event.target.checked }))} />
          </div>
        </div>
      </section>

      <section className={df.section} data-testid="ct-pxe-search-extra">
        <h2 className={df.sectionTitle}>Điều kiện thêm</h2>
        <div className={df.row4} onKeyDown={onEnter}>
          <Field label="Vụ việc" testId="ct-pxe-search-maVv" maxLength={30} value={search.maVv} onChange={setText('maVv')} />
          <Field label="Hợp đồng" testId="ct-pxe-search-maHd" maxLength={30} value={search.maHd} onChange={setText('maHd')} />
          <Field label="Phí" testId="ct-pxe-search-maPhi" maxLength={30} value={search.maPhi} onChange={setText('maPhi')} />
          <Field label="Sản phẩm" testId="ct-pxe-search-maSp" maxLength={30} value={search.maSp} onChange={setText('maSp')} />
          <Field label="Khế ước" testId="ct-pxe-search-maKu" maxLength={30} value={search.maKu} onChange={setText('maKu')} />
          <Field label="Trung tâm lợi nhuận" testId="ct-pxe-search-maTtln" maxLength={30} value={search.maTtln} onChange={setText('maTtln')} />
          <Field label="Trung tâm chi phí" testId="ct-pxe-search-maTtcp" maxLength={30} value={search.maTtcp} onChange={setText('maTtcp')} />
          <Field label="Bộ phận" testId="ct-pxe-search-maBp" maxLength={30} value={search.maBp} onChange={setText('maBp')} />
          <Field label="Hồ sơ" testId="ct-pxe-search-maHs" maxLength={30} value={search.maHs} onChange={setText('maHs')} />
          <Field label="Công đoạn" testId="ct-pxe-search-maCd" maxLength={30} value={search.maCd} onChange={setText('maCd')} />
          <Field label="Mã tự do 1" testId="ct-pxe-search-maTd1" maxLength={30} value={search.maTd1} onChange={setText('maTd1')} />
          <Field label="Mã tự do 2" testId="ct-pxe-search-maTd2" maxLength={30} value={search.maTd2} onChange={setText('maTd2')} />
          <Field label="Mã tự do 3" testId="ct-pxe-search-maTd3" maxLength={30} value={search.maTd3} onChange={setText('maTd3')} />
          <Field label="Mã tự do 4" testId="ct-pxe-search-maTd4" maxLength={30} value={search.maTd4} onChange={setText('maTd4')} />
          <Field label="Mã tự do 5" testId="ct-pxe-search-maTd5" maxLength={30} value={search.maTd5} onChange={setText('maTd5')} />
        </div>
      </section>

      {error && <div className={df.errorBanner}>{error}</div>}
      {loading && <div className={df.loading}>Đang tải...</div>}
      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-pxe-grid">
          <thead>
            <tr>
              <th style={{ width: 70 }}>Số C.từ</th>
              <th style={{ width: 70 }}>Ngày C.từ</th>
              <th style={{ width: 100 }}>Đối tượng</th>
              <th style={{ width: 250 }}>Tên đối tượng</th>
              <th style={{ width: 120 }}>Tổng Phát sinh</th>
              <th style={{ width: 80 }}>Tổng Ps NT</th>
              <th style={{ width: 70 }}>Ngoại tệ</th>
              <th style={{ width: 100 }}>Mã kho</th>
              <th style={{ width: 70 }}>Kho nhập</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => (
              <tr
                key={row.sttRec}
                aria-selected={row.sttRec === selectedSttRec}
                style={row.sttRec === selectedSttRec ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                onClick={() => setSelectedSttRec(row.sttRec)}
              >
                <td>{row.soCt}</td>
                <td>{formatDate(row.ngayCt)}</td>
                <td>{row.maKh}</td>
                <td>{row.tenKh}</td>
                <td>{showMoney(row.tTien)}</td>
                <td>{showMoney(row.tTienNt)}</td>
                <td>{row.maNt}</td>
                <td>{row.maKho}</td>
                <td>{row.maKhoN}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {!loading && items.length === 0 && (
        <div>{filtering ? 'Không tìm thấy phiếu xuất điều chuyển kho' : 'Không có phiếu xuất điều chuyển kho'}</div>
      )}
    </div>
  );
};

export default PxeListPage;
